def transform(grid):
    from collections import Counter, deque

    h, w = len(grid), len(grid[0])
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    seen = [[False] * w for _ in range(h)]
    out = [[bg] * w for _ in range(h)]

    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == bg or seen[r][c]:
                continue

            q = deque([(r, c)])
            seen[r][c] = True
            cells = []
            while q:
                y, x = q.popleft()
                cells.append((y, x))
                for dy in (-1, 0, 1):
                    for dx in (-1, 0, 1):
                        if dy == 0 and dx == 0:
                            continue
                        ny, nx = y + dy, x + dx
                        if (0 <= ny < h and 0 <= nx < w and
                                not seen[ny][nx] and grid[ny][nx] == color):
                            seen[ny][nx] = True
                            q.append((ny, nx))

            r1 = min(y for y, x in cells)
            r2 = max(y for y, x in cells) + 1
            c1 = min(x for y, x in cells)
            c2 = max(x for y, x in cells) + 1
            area = (r2 - r1) * (c2 - c1)

            # Retain dense rectangular objects, filling any corrupted cells.
            if area >= 4 and len(cells) / area >= 0.65:
                for y in range(r1, r2):
                    for x in range(c1, c2):
                        out[y][x] = color

    return out
